using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class F1WildWalk {
 static float S(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));static float Road(float x)=>-28-.035f*(-51-x)+Mathf.Sin((x+192)*.006f)*6*S(0,100,-x-192);
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");Physics.SyncTransforms();var route=new List<Vector3>();var issues=new List<object>();int samples=0;for(float x=-51;x>=-636;x-=.5f){float z=Road(x);if(!Physics.Raycast(new Vector3(x,20,z),Vector3.down,out var hit,60,~(1<<2),QueryTriggerInteraction.Ignore))throw new Exception("Missing route floor "+x);route.Add(hit.point);if(((int)(-x*2))%4!=0)continue;foreach(float side in new[]{-1.3f,0,1.3f}){samples++;if(!Physics.Raycast(new Vector3(x,20,z+side),Vector3.down,out var h,60,~(1<<2),QueryTriggerInteraction.Ignore)){issues.Add(new{x,side,reason="No floor"});continue;}if(Physics.CheckCapsule(h.point+Vector3.up*.38f,h.point+Vector3.up*1.5f,.31f,~(1<<2),QueryTriggerInteraction.Ignore))issues.Add(new{x,side,reason="Blocked standing capsule"});}}
 var source=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CharacterController>()).First();var g=new GameObject("TemporaryWildernessWalk"){hideFlags=HideFlags.HideAndDontSave,layer=2};var cc=g.AddComponent<CharacterController>();cc.height=source.height;cc.radius=source.radius;cc.center=source.center;cc.skinWidth=source.skinWidth;cc.stepOffset=source.stepOffset;cc.slopeLimit=source.slopeLimit;cc.minMoveDistance=source.minMoveDistance;var results=new List<object>();try{for(int pass=0;pass<2;pass++){cc.enabled=false;g.transform.position=route[0]+Vector3.up*(cc.height*.5f-cc.center.y+.025f);cc.enabled=true;Physics.SyncTransforms();int steps=0;float remaining=0;bool ok=true;Vector3 last=route[0];foreach(var target in route.Skip(1)){last=target;for(int k=0;k<80;k++){Vector3 d=target-g.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.035f)break;cc.Move(d.normalized*Mathf.Min(.09f,remaining)+Vector3.down*.065f);steps++;}if(remaining>.12f){ok=false;break;}}for(int j=0;j<10;j++)cc.Move(Vector3.down*.04f);float error=g.transform.position.y+cc.center.y-cc.height*.5f-last.y;results.Add(new{direction=pass==0?"ExitToWilderness":"ReturnToExit",passed=ok&&Mathf.Abs(error)<.20f,steps,remaining,heightError=error});route.Reverse();}}finally{UnityEngine.Object.DestroyImmediate(g);}var result=new{lengthMetres=585,routeSamples=route.Count,widthSamples=samples,widthIssues=issues,results,playerModified=false,saved=!s.isDirty};File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_WildernessDetail/walk.json"),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
